package com.Polarice3.Goety.api.entities;

import com.Polarice3.Goety.common.effects.GoetyEffects;
import com.Polarice3.Goety.config.AttributesConfig;
import com.Polarice3.Goety.utils.MathHelper;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

public interface IEnchanter extends IAnimated {
    public static String IDLE = "idle";
    public static String ATTACK = "attack";
    public static String ENCHANT = "enchant";
    public static String NOVELTY = "novelty";

    default List<UUID> getEnchantList() {
        return new ArrayList<>();
    }

    default void setEnchantList(List<UUID> list) {
    }

    default int getEnchantCool() {
        return 0;
    }

    default void setEnchantCool(int cool) {
    }

    default int getEnchantTime() {
        return 0;
    }

    default void setEnchantTime(int time) {
    }

    default int enchantTimeLimit() {
        return MathHelper.secondsToTicks(AttributesConfig.EnchanterServantEnchantTime.get());
    }

    default void enchanterTick() {
        if (this instanceof Mob mob) {
            if (mob.level instanceof ServerLevel serverLevel) {
                if (this.getEnchantCool() > 0) {
                    this.setEnchantCool(this.getEnchantCool() - 1);
                }
                if (mob.tickCount > 20) {
                    if (!this.getEnchantList().isEmpty()) {
                        this.getEnchantList().removeIf(uuid -> {
                            Entity entity = serverLevel.getEntity(uuid);
                            if (!(entity instanceof LivingEntity livingEntity)) {
                                return true;
                            }
                            if (mob.isDeadOrDying()) {
                                return true;
                            }
                            if (this.enchantTimeLimit() > -1) {
                                if (this.getEnchantTime() >= this.enchantTimeLimit()) {
                                    this.setEnchantCool(200);
                                    return true;
                                }
                            }
                            if (livingEntity.isDeadOrDying()) {
                                return true;
                            }
                            return livingEntity.distanceTo(mob) > 20.0F;
                        });
                        this.getEnchantList().forEach(uuid -> {
                            Entity entity = serverLevel.getEntity(uuid);
                            if (entity instanceof LivingEntity livingEntity) {
                                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.ENCHANTED.get(), 30), mob);
                            }
                        });
                        this.setEnchantTime(this.getEnchantTime() + 1);
                    } else if (this.getEnchantTime() > 0) {
                        this.setEnchantTime(0);
                    }
                }
            }
        }
    }

    default void setShowArms(boolean showArms) {
    }

    default boolean showArms() {
        return !this.isCurrentAnimation(IEnchanter.IDLE);
    }

    default void readEnchanterData(CompoundTag pCompound) {
        if (pCompound.contains("EnchantCool")){
            this.setEnchantCool(pCompound.getInt("EnchantCool"));
        }
        if (pCompound.contains("EnchantTime")){
            this.setEnchantTime(pCompound.getInt("EnchantTime"));
        }
        if (pCompound.contains("EnchantTargets")){
            ListTag listTag = pCompound.getList("EnchantTargets", 8);
            List<UUID> list = new ArrayList<>();
            for(int i = 0; i < listTag.size(); ++i) {
                list.add(UUID.fromString(listTag.getString(i)));
            }
            this.setEnchantList(list);
        }
    }

    default void addEnchanterData(CompoundTag pCompound) {
        pCompound.putInt("EnchantCool", this.getEnchantCool());
        pCompound.putInt("EnchantTime", this.getEnchantTime());
        if (!this.getEnchantList().isEmpty()) {
            ListTag listTag = new ListTag();
            for (UUID uuid : this.getEnchantList()) {
                listTag.add(StringTag.valueOf(uuid.toString()));
            }
            pCompound.put("EnchantTargets", listTag);
        }
    }
}

package com.Polarice3.Goety.api.entities;

import com.Polarice3.Goety.utils.BlockFinder;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.AbstractFurnaceBlockEntity;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.Optional;

public interface IMobCrafter {

    default Optional<BlockPos> getFurnacePos() {
        return Optional.empty();
    }

    default void setFurnacePos(@Nullable BlockPos blockPos) {
    }

    default Optional<BlockPos> getCraftTablePos() {
        return Optional.empty();
    }

    default void setCraftTablePos(@Nullable BlockPos blockPos) {
    }

    default void setUsingFurnace(boolean cooking) {
    }

    default boolean isUsingFurnace() {
        return false;
    }

    default boolean isFurnace(BlockState blockState) {
        return false;
    }

    default void setCrafting(boolean crafting) {
    }

    default boolean isCrafting() {
        return false;
    }

    default boolean isCraftTable(BlockState blockState) {
        return false;
    }

    default boolean isFurnaceActuallyCooking() {
        if (this.getFurnacePos().isEmpty()) {
            return false;
        }
        if (this instanceof Entity entity) {
            BlockEntity be = entity.level.getBlockEntity(this.getFurnacePos().get());
            if (be instanceof AbstractFurnaceBlockEntity blockEntity) {
                return blockEntity.litTime > 0;
            }
        }
        return false;
    }

    default void setFurnaceLit(boolean lit) {
        if (this.getFurnacePos().isEmpty()) {
            return;
        }
        if (this instanceof Entity entity) {
            BlockPos blockPos = this.getFurnacePos().get();
            BlockState blockState = entity.level.getBlockState(blockPos);
            if ((this.isFurnace(blockState))
                    && blockState.hasProperty(BlockStateProperties.LIT)
                    && blockState.getValue(BlockStateProperties.LIT) != lit) {
                entity.level.setBlock(blockPos, blockState.setValue(BlockStateProperties.LIT, lit), 3);
            }
        }
    }

    default List<Mob> getNearbyCraftTableUsers(Level level, AABB aabb, BlockPos blockPos) {
        return level.getEntitiesOfClass(Mob.class, aabb, mob -> mob instanceof IMobCrafter crafter && crafter.getCraftTablePos().isPresent()
                && BlockFinder.samePos(crafter.getCraftTablePos().get(), blockPos)
                && crafter.isCrafting()
                && crafter != this);
    }

    default void readCrafterData(CompoundTag compound){
        if (compound.contains("FurnacePos")){
            this.setFurnacePos(NbtUtils.readBlockPos(compound.getCompound("FurnacePos")));
        }
        if (compound.contains("CraftTablePos")){
            this.setCraftTablePos(NbtUtils.readBlockPos(compound.getCompound("CraftTablePos")));
        }
    }

    default void saveCrafterData(CompoundTag compound){
        if (this.getFurnacePos().isPresent()) {
            compound.put("FurnacePos", NbtUtils.writeBlockPos(this.getFurnacePos().get()));
        }
        if (this.getCraftTablePos().isPresent()) {
            compound.put("CraftTablePos", NbtUtils.writeBlockPos(this.getCraftTablePos().get()));
        }
    }
}

package com.Polarice3.Goety.common.entities.ai;

import com.Polarice3.Goety.api.entities.IMobCrafter;
import com.Polarice3.Goety.utils.BlockFinder;
import net.minecraft.commands.arguments.EntityAnchorArgument;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.npc.InventoryCarrier;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.Nullable;

import java.util.EnumSet;
import java.util.List;

public class MobCraftingGoal<T extends Mob & IMobCrafter> extends Goal {
    public T mob;
    public int tryTicks;
    @Nullable
    public BlockPos craftTable;
    public int workTick;
    public int craftTime;
    public int checkCooldown = 0;
    public long nextCooldown = 0L;
    public int lastInventorySize = -1;
    public float speedModifier;
    public boolean cachedCanCraft = false;

    public MobCraftingGoal(T mob, int craftTime, float speedModifier) {
        this.mob = mob;
        this.craftTime = craftTime;
        this.speedModifier = speedModifier;
        this.setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
    }

    public boolean canStartCrafting() {
        return false;
    }

    @Override
    public boolean canUse() {
        if (this.mob.getTarget() != null) {
            return false;
        }
        long now = this.mob.level.getGameTime();
        if (!this.inventoryChanged() && now < this.nextCooldown) {
            return this.cachedCanCraft && !this.mob.isUsingFurnace()
                    && this.mob.level instanceof ServerLevel;
        }
        this.nextCooldown = now + 40L;
        this.cachedCanCraft = this.craftCheck();
        return this.cachedCanCraft;
    }

    public boolean craftCheck() {
        if (this.mob.level instanceof ServerLevel) {
            if (this.canStartCrafting()) {
                this.craftTable = this.findCraftTable();
                if (this.craftTable != null) {
                    this.mob.setCraftTablePos(this.craftTable);
                }
                return this.craftTable != null && this.mob.getTarget() == null;
            }
        }
        return false;
    }

    public boolean inventoryChanged() {
        if (this.mob instanceof InventoryCarrier carrier) {
            int currentSize = 0;
            SimpleContainer inv = carrier.getInventory();
            for (int i = 0; i < inv.getContainerSize(); i++) {
                currentSize += inv.getItem(i).getCount();
            }
            if (currentSize != this.lastInventorySize) {
                this.lastInventorySize = currentSize;
                return true;
            }
        }
        return false;
    }

    public boolean canContinueToUse() {
        if (this.mob.level instanceof ServerLevel serverLevel) {
            if (this.canStartCrafting()) {
                if (this.craftTable != null) {
                    if (this.getNearbyCraftTableUsers(serverLevel, new AABB(this.craftTable).inflate(4.0D), this.craftTable).isEmpty()) {
                        if (this.tryTicks <= 1200) {
                            BlockState blockState = this.mob.level.getBlockState(this.craftTable);
                            return this.mob.isCraftTable(blockState);
                        }
                    }
                }
            }
        }
        return false;
    }

    public void start() {
        this.moveMobToBlock();
        this.tryTicks = 0;
    }

    protected void moveMobToBlock() {
        if (this.craftTable == null) {
            this.stop();
            return;
        }
        this.mob.getNavigation().moveTo((double)((float)this.craftTable.getX()) + 0.5D, (double)(this.craftTable.getY() + 1), (double)((float)this.craftTable.getZ()) + 0.5D, this.speedModifier);
    }

    @Override
    public void stop() {
        this.craftTable = null;
        this.mob.setCraftTablePos(null);
        this.tryTicks = 0;
        this.workTick = 0;
        this.mob.setCrafting(false);
        this.returnIdleAnimation();
        this.nextCooldown = 0L;
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void tick() {
        if (this.craftTable == null) {
            this.stop();
            return;
        }
        if (this.mob.level instanceof ServerLevel serverLevel) {
            if (this.mob.distanceToSqr(Vec3.atCenterOf(this.craftTable)) > Mth.square(2)) {
                ++this.tryTicks;
                if (this.shouldRecalculatePath()) {
                    this.mob.getNavigation().moveTo((double)((float)this.craftTable.getX()) + 0.5D, (double)this.craftTable.getY(), (double)((float)this.craftTable.getZ()) + 0.5D, this.speedModifier);
                }
                if (this.mob.isCrafting()) {
                    this.mob.setCrafting(false);
                }
            } else {
                this.mob.getNavigation().stop();
                this.mob.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(this.craftTable));
                this.tryTicks = 0;
                ++this.workTick;
                if (!this.mob.isCrafting()) {
                    this.mob.setCrafting(true);
                }

                if (this.workTick == this.timeToAnimateWork()) {
                    this.playWorkAnimation();
                }

                if (this.workTick >= this.craftTime) {
                    this.workTick = 0;
                    this.onCraft(serverLevel);
                    this.returnIdleAnimation();
                }
            }
        }
    }

    public int timeToAnimateWork(){
        return this.craftTime;
    }

    public void playWorkAnimation() {
    }

    public void returnIdleAnimation() {
    }

    public void onCraft(ServerLevel serverLevel) {
    }

    public boolean shouldRecalculatePath() {
        return this.tryTicks % 40 == 0;
    }

    public List<Mob> getNearbyCraftTableUsers(Level level, AABB aabb, BlockPos blockPos) {
        return level.getEntitiesOfClass(Mob.class, aabb, mob -> mob instanceof IMobCrafter chef && chef.getCraftTablePos().isPresent()
                && BlockFinder.samePos(chef.getCraftTablePos().get(), blockPos)
                && chef.isCrafting()
                && chef != this.mob);
    }

    public BlockPos findCraftTable(){
        int i = 8;
        int j = 1;
        for(int k = 0; k <= j; k = k > 0 ? -k : 1 - k) {
            for(int l = 0; l < i; ++l) {
                for(int i1 = 0; i1 <= l; i1 = i1 > 0 ? -i1 : 1 - i1) {
                    for(int j1 = i1 < l && i1 > -l ? l : 0; j1 <= l; j1 = j1 > 0 ? -j1 : 1 - j1) {
                        BlockPos blockPos1 = this.mob.blockPosition().offset(i1, k - 1, j1);
                        BlockState blockState = this.mob.level.getBlockState(blockPos1);
                        if (this.mob.isCraftTable(blockState)){
                            if (this.getNearbyCraftTableUsers(this.mob.level, new AABB(blockPos1).inflate(4.0D), blockPos1).isEmpty()) {
                                return blockPos1;
                            }
                        }
                    }
                }
            }
        }
        return null;
    }
}

package com.Polarice3.Goety.common.entities.ai;

import com.Polarice3.Goety.api.entities.IMobCrafter;
import com.Polarice3.Goety.utils.BlockFinder;
import net.minecraft.commands.arguments.EntityAnchorArgument;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.npc.InventoryCarrier;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.Nullable;

import java.util.EnumSet;
import java.util.List;

public class MobFurnaceGoal<T extends Mob & IMobCrafter> extends Goal {
    public static int COOK_TIME = 100;
    public T mob;
    protected int tryTicks;
    @Nullable
    public BlockPos furnace;
    public int workTick;
    public int furnaceTime;
    public int checkCooldown = 0;
    public long nextCooldown = 0L;
    public int lastInventorySize = -1;
    public float speedModifier;
    public boolean cachedCanSmelt = false;
    public boolean playSound = false;

    public MobFurnaceGoal(T mob, int furnaceTime, float speedModifier) {
        this.mob = mob;
        this.furnaceTime = furnaceTime;
        this.speedModifier = speedModifier;
        this.setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
    }

    public boolean canStartFurnaceUsing() {
        return false;
    }

    @Override
    public boolean canUse() {
        if (this.mob.getTarget() != null) {
            return false;
        }
        long now = this.mob.level.getGameTime();
        if (!this.inventoryChanged() && now < this.nextCooldown) {
            return this.cachedCanSmelt && !this.mob.isUsingFurnace()
                    && this.mob.level instanceof ServerLevel;
        }
        this.nextCooldown = now + 40L;
        this.cachedCanSmelt = this.smeltCheck();
        return this.cachedCanSmelt;
    }

    public boolean smeltCheck() {
        if (this.mob.level instanceof ServerLevel) {
            if (this.canStartFurnaceUsing()) {
                this.furnace = this.findFurnace();
                if (this.furnace != null) {
                    this.mob.setFurnacePos(this.furnace);
                }
                return this.furnace != null && this.mob.getTarget() == null;
            }
        }
        return false;
    }

    public boolean inventoryChanged() {
        if (this.mob instanceof InventoryCarrier carrier) {
            int currentSize = 0;
            SimpleContainer inv = carrier.getInventory();
            for (int i = 0; i < inv.getContainerSize(); i++) {
                currentSize += inv.getItem(i).getCount();
            }
            if (currentSize != this.lastInventorySize) {
                this.lastInventorySize = currentSize;
                return true;
            }
        }
        return false;
    }

    @Override
    public boolean canContinueToUse() {
        if (this.mob.level instanceof ServerLevel serverLevel) {
            if (this.canStartFurnaceUsing()) {
                if (this.furnace != null) {
                    if (this.getNearbyFurnaceUsers(serverLevel, new AABB(this.furnace).inflate(4.0D), this.furnace).isEmpty()) {
                        if (this.tryTicks <= 1200) {
                            BlockState blockState = this.mob.level.getBlockState(this.furnace);
                            return this.mob.isFurnace(blockState);
                        }
                    }
                }
            }
        }
        return false;
    }

    public void start() {
        this.moveMobToBlock();
        this.tryTicks = 0;
    }

    protected void moveMobToBlock() {
        if (this.furnace == null) {
            this.stop();
            return;
        }
        this.mob.getNavigation().moveTo((double)((float)this.furnace.getX()) + 0.5D, (double)(this.furnace.getY() + 1), (double)((float)this.furnace.getZ()) + 0.5D, this.speedModifier);
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void stop() {
        if (!this.mob.isFurnaceActuallyCooking()) {
            this.mob.setFurnaceLit(false);
        }
        this.furnace = null;
        this.mob.setFurnacePos(null);
        this.tryTicks = 0;
        this.workTick = 0;
        this.mob.setUsingFurnace(false);
        this.nextCooldown = 0L;
    }

    public void tick(){
        if (this.furnace == null) {
            this.stop();
            return;
        }
        if (this.mob.level instanceof ServerLevel serverLevel) {
            if (this.mob.distanceToSqr(Vec3.atCenterOf(this.furnace)) > Mth.square(2)) {
                ++this.tryTicks;
                if (this.shouldRecalculatePath()) {
                    this.mob.getNavigation().moveTo((double)((float)this.furnace.getX()) + 0.5D, (double)this.furnace.getY(), (double)((float)this.furnace.getZ()) + 0.5D, this.speedModifier);
                }
                if (this.mob.isUsingFurnace()) {
                    this.mob.setUsingFurnace(false);
                    if (!this.mob.isFurnaceActuallyCooking()) {
                        this.mob.setFurnaceLit(false);
                    }
                }
            } else {
                this.mob.getNavigation().stop();
                this.mob.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(this.furnace));
                this.tryTicks = 0;
                ++this.workTick;
                if (!this.mob.isUsingFurnace()) {
                    this.mob.setUsingFurnace(true);
                }
                if (!this.playSound) {
                    this.mob.setFurnaceLit(true);
                    this.playSound = true;
                }
                if (this.workTick > COOK_TIME) {
                    this.onSmelt(serverLevel);
                    this.playSound = false;
                    this.workTick = 0;
                    if (!this.mob.isFurnaceActuallyCooking()) {
                        this.mob.setFurnaceLit(false);
                    }
                }
            }
        }
    }

    public void onSmelt(ServerLevel serverLevel) {
    }

    public boolean shouldRecalculatePath() {
        return this.tryTicks % 40 == 0;
    }

    public List<Mob> getNearbyFurnaceUsers(Level level, AABB aabb, BlockPos blockPos) {
        return level.getEntitiesOfClass(Mob.class, aabb, mob -> mob instanceof IMobCrafter chef && chef.getFurnacePos().isPresent()
                && BlockFinder.samePos(chef.getFurnacePos().get(), blockPos)
                && chef.isUsingFurnace()
                && chef != this.mob);
    }

    public BlockPos findFurnace(){
        int i = 8;
        int j = 1;
        for(int k = 0; k <= j; k = k > 0 ? -k : 1 - k) {
            for(int l = 0; l < i; ++l) {
                for(int i1 = 0; i1 <= l; i1 = i1 > 0 ? -i1 : 1 - i1) {
                    for(int j1 = i1 < l && i1 > -l ? l : 0; j1 <= l; j1 = j1 > 0 ? -j1 : 1 - j1) {
                        BlockPos blockPos1 = this.mob.blockPosition().offset(i1, k - 1, j1);
                        BlockState blockState = this.mob.level.getBlockState(blockPos1);
                        if (this.mob.isFurnace(blockState)){
                            if (this.getNearbyFurnaceUsers(this.mob.level, new AABB(blockPos1).inflate(4.0D), blockPos1).isEmpty()) {
                                return blockPos1;
                            }
                        }
                    }
                }
            }
        }
        return null;
    }
}

