    public boolean canBreed() {
        boolean flag = true;
        if (!MobsConfig.IllagerServantAllBreed.get()){
            flag = this.getType() == ModEntityType.NEOLLAGER.get();
        }
        return flag
                && this.foodLevel + this.countFoodPointsInInventory() >= 12
                && !this.isSleeping()
                && this.breedCool <= 0
                && this.hurtTime <= 0
                && this.getTarget() == null
                && !this.isFollowing()
                && !this.isCommanded()
                && !this.isCelebrating()
                && !this.isRaiding()
                && !this.isBaby();
    }

