            return living -> {
                if (living instanceof INeedSaddle saddle && living instanceof RaiderServant mob) {
                    return mob.getTrueOwner() == owned.getTrueOwner()
                            && !saddle.hasSaddle()
                            && mob.getTarget() == null;
